import{_ as i,o as a,c as r,ag as o}from"./chunks/framework.DQQHyi2x.js";const p=JSON.parse('{"title":"Codex CLI and Multi-Provider v2 Plan","description":"","frontmatter":{},"headers":[],"relativePath":"plans/2026-05-26-codex-cli-v2-plan.md","filePath":"plans/2026-05-26-codex-cli-v2-plan.md"}'),t={name:"plans/2026-05-26-codex-cli-v2-plan.md"};function l(n,e,d,s,c,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="codex-cli-and-multi-provider-v2-plan" tabindex="-1">Codex CLI and Multi-Provider v2 Plan <a class="header-anchor" href="#codex-cli-and-multi-provider-v2-plan" aria-label="Permalink to &quot;Codex CLI and Multi-Provider v2 Plan&quot;">​</a></h1><p><strong>Date:</strong> 2026-05-26<br><strong>Status:</strong> Follow-up plan<br><strong>Related work:</strong> PR #139, issues #140 and #142, <code>docs/plans/2026-05-25-codex-cli-support.md</code><br><strong>Scope:</strong> Deferred v1 bullets, multi-provider hardening, Codex parity investigation, E2E coverage</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Turn the v1 Codex CLI support into a durable multi-provider foundation.</p><p>v1 proved the architecture: Claude Deck can detect, configure, launch, diagnose, and back up Codex CLI alongside Claude Code. v2 should close the deliberately deferred gaps, deepen the shared provider model, and make the mixed-provider experience feel native rather than newly grafted on.</p><p>This plan is not a continuation of the v1 implementation checklist. It is the next planning layer for the items v1 intentionally narrowed plus the extra work exposed by the first implementation.</p><h2 id="v1-baseline" tabindex="-1">V1 Baseline <a class="header-anchor" href="#v1-baseline" aria-label="Permalink to &quot;V1 Baseline&quot;">​</a></h2><p>Already shipped:</p><ul><li>Provider registry for Claude Code and Codex CLI.</li><li>Provider status, diagnostics, and CLI execution safeguards.</li><li>Agent Bridge backend with Codex discovery and spawn/resume/fork support.</li><li>Provider context and provider-aware UI routing.</li><li>Codex TOML config loading and whitelisted structured edits.</li><li>Backup-before-write for Codex config changes.</li><li>Codex MCP inventory plus MCP add/remove controls.</li><li>Codex plugin inventory in read-only mode.</li><li>Export-only Codex backups.</li><li>Provider-aware dashboard, header, sidebar, and docs.</li><li>Backend tests and build verification.</li></ul><h2 id="deferred-from-v1" tabindex="-1">Deferred From V1 <a class="header-anchor" href="#deferred-from-v1" aria-label="Permalink to &quot;Deferred From V1&quot;">​</a></h2><p>These came directly from the original v1 plan but were intentionally reduced:</p><ul><li>Full frontend <code>cc-bridge</code> to <code>agent-bridge</code> feature/module rename.</li><li>Richer mixed-provider Agent Bridge UX with an explicit All / Claude Code / Codex filter model.</li><li>Codex history and model cache read-only surfaces.</li><li>Full Codex profile resolver.</li><li>Dedicated Codex cards for profiles, rules, features, and plugin workflows.</li><li>Codex plugin mutation.</li><li>Codex backup restore policy.</li><li>Broader browser-level E2E smoke coverage.</li><li>Deeper usage/context parity investigation for Codex.</li></ul><h2 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h2><ul><li>Do not expose Codex auth secrets in raw viewers or backups by default.</li><li>Do not add broad arbitrary Codex CLI execution.</li><li>Do not treat Claude-only metrics as provider-neutral until Codex has reliable local data.</li><li>Do not add a third provider until the two-provider contract is tighter.</li><li>Do not support automatic Codex restore until the restore safety model is explicitly designed and tested.</li></ul><h2 id="workstream-1-agent-bridge-v2" tabindex="-1">Workstream 1: Agent Bridge v2 <a class="header-anchor" href="#workstream-1-agent-bridge-v2" aria-label="Permalink to &quot;Workstream 1: Agent Bridge v2&quot;">​</a></h2><h3 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h3><p>Make the mixed Claude Code + Codex session experience first-class.</p><h3 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Rename frontend feature code from <code>cc-bridge</code> toward <code>agent-bridge</code> where practical.</li><li>Keep route compatibility for existing <code>/cc-bridge</code> links if needed.</li><li>Add explicit provider filters: <ul><li>All agents</li><li>Claude Code</li><li>Codex CLI</li></ul></li><li>Make provider badges, empty states, and unsupported actions consistent.</li><li>Improve new-session dialog structure: <ul><li>provider choice first</li><li>then provider-specific fields</li><li>clearer dangerous-option warnings</li></ul></li><li>Ensure mixed sessions can be viewed and attached side by side without hidden provider assumptions.</li></ul><h3 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>A mixed tmux fleet shows Claude Code and Codex sessions together by default.</li><li>Provider filtering works without losing selected terminal state unexpectedly.</li><li>Codex and Claude Code session cards use shared layout with provider-specific actions.</li><li>Frontend naming no longer leaks <code>cc-bridge</code> into newly touched public UI strings.</li><li>Existing deep links continue working or redirect cleanly.</li></ul><h2 id="workstream-2-codex-session-and-history-surfaces" tabindex="-1">Workstream 2: Codex Session and History Surfaces <a class="header-anchor" href="#workstream-2-codex-session-and-history-surfaces" aria-label="Permalink to &quot;Workstream 2: Codex Session and History Surfaces&quot;">​</a></h2><h3 id="objective-1" tabindex="-1">Objective <a class="header-anchor" href="#objective-1" aria-label="Permalink to &quot;Objective&quot;">​</a></h3><p>Investigate and expose reliable Codex history/session metadata without inventing unsupported semantics.</p><h3 id="scope-1" tabindex="-1">Scope <a class="header-anchor" href="#scope-1" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Inspect <code>$CODEX_HOME/history.jsonl</code>.</li><li>Inspect <code>$CODEX_HOME/models_cache.json</code>.</li><li>Identify whether Codex has stable session IDs, timestamps, project paths, model choices, and message summaries.</li><li>Add read-only backend services if the files are stable enough.</li><li>Add a Codex history/session page only if the data quality is good.</li><li>Otherwise, document what is missing and keep this out of product UI.</li></ul><h3 id="acceptance-criteria-1" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-1" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>Decision recorded: supported surface, partial diagnostics-only surface, or no UI.</li><li>No raw secrets or sensitive prompt bodies are exposed without deliberate UI framing.</li><li>Tests cover malformed, missing, and large history/cache files.</li></ul><h2 id="workstream-3-codex-plugin-management" tabindex="-1">Workstream 3: Codex Plugin Management <a class="header-anchor" href="#workstream-3-codex-plugin-management" aria-label="Permalink to &quot;Workstream 3: Codex Plugin Management&quot;">​</a></h2><h3 id="objective-2" tabindex="-1">Objective <a class="header-anchor" href="#objective-2" aria-label="Permalink to &quot;Objective&quot;">​</a></h3><p>Move from read-only plugin inventory to safe mutation workflows if Codex CLI behavior is stable enough.</p><h3 id="scope-2" tabindex="-1">Scope <a class="header-anchor" href="#scope-2" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Validate local <code>codex plugin</code> command behavior for: <ul><li>install</li><li>remove/uninstall</li><li>enable/disable, if supported</li><li>update, if supported</li><li>marketplace/list metadata</li></ul></li><li>Model plugin operations as provider-owned commands, not raw shell strings.</li><li>Add strict allowlists and argument validation.</li><li>Add confirmation UX for destructive actions.</li><li>Preserve read-only mode when mutation support is unavailable or ambiguous.</li></ul><h3 id="acceptance-criteria-2" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-2" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>Plugin mutation commands use fixed binary resolution and <code>shell=False</code>.</li><li>All plugin identifiers are validated.</li><li>Destructive operations require explicit confirmation.</li><li>Failed CLI operations return actionable errors.</li><li>Tests cover supported operations and refusal paths.</li></ul><h2 id="workstream-4-codex-configuration-depth" tabindex="-1">Workstream 4: Codex Configuration Depth <a class="header-anchor" href="#workstream-4-codex-configuration-depth" aria-label="Permalink to &quot;Workstream 4: Codex Configuration Depth&quot;">​</a></h2><h3 id="objective-3" tabindex="-1">Objective <a class="header-anchor" href="#objective-3" aria-label="Permalink to &quot;Objective&quot;">​</a></h3><p>Fill the remaining Codex config UI gaps without overfitting to unstable TOML details.</p><h3 id="scope-3" tabindex="-1">Scope <a class="header-anchor" href="#scope-3" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Add a Codex profile resolver: <ul><li>active profile</li><li><code>profile-v2</code> reference</li><li>profile TOML files</li><li>overridden keys</li></ul></li><li>Add dedicated cards where useful: <ul><li>profiles</li><li>rules</li><li>features</li><li>project trust</li></ul></li><li>Improve raw TOML editing only if validation and recovery are robust enough.</li><li>Keep structured edits whitelisted.</li></ul><h3 id="acceptance-criteria-3" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-3" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>Users can see where effective Codex values come from.</li><li>Profile v2 files are visible and safely editable only for approved keys.</li><li>Rules files can be viewed without exposing auth/cache/history files.</li><li>Parse errors are clear and do not block unrelated read-only views.</li></ul><h2 id="workstream-5-backup-export-and-restore-policy" tabindex="-1">Workstream 5: Backup, Export, and Restore Policy <a class="header-anchor" href="#workstream-5-backup-export-and-restore-policy" aria-label="Permalink to &quot;Workstream 5: Backup, Export, and Restore Policy&quot;">​</a></h2><h3 id="objective-4" tabindex="-1">Objective <a class="header-anchor" href="#objective-4" aria-label="Permalink to &quot;Objective&quot;">​</a></h3><p>Design a serious Codex backup policy instead of casually adding restore.</p><h3 id="scope-4" tabindex="-1">Scope <a class="header-anchor" href="#scope-4" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Keep export-only behavior as the default.</li><li>Define restore categories: <ul><li>safe restore: non-secret config/rules/profile files</li><li>unsafe restore: auth, tokens, cache, history</li><li>unsupported restore: generated or version-sensitive files</li></ul></li><li>Add restore preview for safe files only if path checks and parse validation are strong.</li><li>Consider an explicit advanced export mode for history/cache, but keep auth excluded unless there is a compelling reason.</li></ul><h3 id="acceptance-criteria-4" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-4" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>Restore never writes outside <code>$CODEX_HOME</code>.</li><li>Restore validates TOML before replacing active config.</li><li>Restore creates a pre-restore backup.</li><li>Auth files remain excluded by default.</li><li>UI clearly distinguishes export, restore preview, and actual restore.</li></ul><h2 id="workstream-6-provider-capability-matrix" tabindex="-1">Workstream 6: Provider Capability Matrix <a class="header-anchor" href="#workstream-6-provider-capability-matrix" aria-label="Permalink to &quot;Workstream 6: Provider Capability Matrix&quot;">​</a></h2><h3 id="objective-5" tabindex="-1">Objective <a class="header-anchor" href="#objective-5" aria-label="Permalink to &quot;Objective&quot;">​</a></h3><p>Make provider support explicit in the UI and API.</p><h3 id="scope-5" tabindex="-1">Scope <a class="header-anchor" href="#scope-5" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Expand provider capability metadata beyond booleans where useful: <ul><li>supported</li><li>read-only</li><li>write-capable</li><li>unsupported</li><li>unknown</li></ul></li><li>Use capability metadata to drive: <ul><li>sidebar visibility</li><li>diagnostics</li><li>empty states</li><li>disabled actions</li><li>docs/API output</li></ul></li><li>Make Claude-only surfaces explicit rather than implied.</li></ul><h3 id="acceptance-criteria-5" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-5" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>The UI can explain why an action is hidden or disabled.</li><li>Capability metadata is tested for both Claude Code and Codex.</li><li>Adding a future provider does not require hardcoding every nav decision in React.</li></ul><h2 id="workstream-7-usage-and-context-parity-investigation" tabindex="-1">Workstream 7: Usage and Context Parity Investigation <a class="header-anchor" href="#workstream-7-usage-and-context-parity-investigation" aria-label="Permalink to &quot;Workstream 7: Usage and Context Parity Investigation&quot;">​</a></h2><h3 id="objective-6" tabindex="-1">Objective <a class="header-anchor" href="#objective-6" aria-label="Permalink to &quot;Objective&quot;">​</a></h3><p>Decide whether Codex can support meaningful usage/context views.</p><h3 id="scope-6" tabindex="-1">Scope <a class="header-anchor" href="#scope-6" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Investigate local Codex data sources for: <ul><li>model usage</li><li>token usage</li><li>session duration</li><li>project activity</li><li>context/tool usage</li></ul></li><li>Compare against existing Claude Code usage/context surfaces.</li><li>Add diagnostics-only summaries if data is partial.</li><li>Avoid fake precision.</li></ul><h3 id="acceptance-criteria-6" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-6" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>A short decision doc states what Codex can and cannot support.</li><li>Any UI added labels Codex metrics accurately.</li><li>Claude-only usage/context pages remain clearly labeled until parity is real.</li></ul><h2 id="workstream-8-provider-contract-hardening" tabindex="-1">Workstream 8: Provider Contract Hardening <a class="header-anchor" href="#workstream-8-provider-contract-hardening" aria-label="Permalink to &quot;Workstream 8: Provider Contract Hardening&quot;">​</a></h2><h3 id="objective-7" tabindex="-1">Objective <a class="header-anchor" href="#objective-7" aria-label="Permalink to &quot;Objective&quot;">​</a></h3><p>Make the provider layer boring enough that a third provider can be added later without another architectural retrofit.</p><h3 id="scope-7" tabindex="-1">Scope <a class="header-anchor" href="#scope-7" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Review <code>AgentProvider</code> boundaries after v1 usage.</li><li>Separate provider metadata, CLI commands, config files, session discovery, and backup behaviors cleanly.</li><li>Reduce provider-specific conditionals in route handlers and frontend components.</li><li>Add contract tests for shared provider behavior.</li><li>Document provider implementation requirements.</li></ul><h3 id="acceptance-criteria-7" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-7" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>Provider-specific logic lives primarily in provider modules.</li><li>Shared routes use provider interfaces rather than provider id conditionals where practical.</li><li>Tests catch missing capabilities, unsafe command exposure, and malformed provider responses.</li></ul><h2 id="workstream-9-e2e-and-smoke-coverage" tabindex="-1">Workstream 9: E2E and Smoke Coverage <a class="header-anchor" href="#workstream-9-e2e-and-smoke-coverage" aria-label="Permalink to &quot;Workstream 9: E2E and Smoke Coverage&quot;">​</a></h2><h3 id="objective-8" tabindex="-1">Objective <a class="header-anchor" href="#objective-8" aria-label="Permalink to &quot;Objective&quot;">​</a></h3><p>Add browser-level confidence for the multi-provider flows.</p><h3 id="scope-8" tabindex="-1">Scope <a class="header-anchor" href="#scope-8" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Use temp config homes for Codex and Claude where possible.</li><li>Add E2E coverage for: <ul><li>provider switching</li><li>dashboard provider status</li><li>Agent Bridge provider filters</li><li>Codex settings edit in a temp <code>$CODEX_HOME</code></li><li>Codex MCP add/remove against a controlled fixture or mocked CLI</li><li>Codex backup export</li><li>unsupported/disabled provider actions</li></ul></li><li>Keep manual smoke checklist for local tmux attachment because terminal interaction is environment-sensitive.</li></ul><h3 id="acceptance-criteria-8" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-8" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>E2E tests run in CI or are clearly marked as local-only with documented prerequisites.</li><li>Tests do not mutate real <code>~/.codex</code> or <code>~/.claude</code>.</li><li>Manual smoke checklist is updated and repeatable.</li></ul><h2 id="workstream-10-documentation-and-product-framing" tabindex="-1">Workstream 10: Documentation and Product Framing <a class="header-anchor" href="#workstream-10-documentation-and-product-framing" aria-label="Permalink to &quot;Workstream 10: Documentation and Product Framing&quot;">​</a></h2><h3 id="objective-9" tabindex="-1">Objective <a class="header-anchor" href="#objective-9" aria-label="Permalink to &quot;Objective&quot;">​</a></h3><p>Make the product story match the multi-provider reality.</p><h3 id="scope-9" tabindex="-1">Scope <a class="header-anchor" href="#scope-9" aria-label="Permalink to &quot;Scope&quot;">​</a></h3><ul><li>Update docs once v2 features land: <ul><li>Agent Bridge mixed-provider workflows</li><li>Codex config/profile/rules handling</li><li>Codex plugin management safety model</li><li>backup/export/restore policy</li><li>provider capability matrix</li></ul></li><li>Decide whether public copy still leans on &quot;Claude Deck&quot; or starts introducing a broader &quot;local agent console&quot; framing more strongly.</li><li>Add examples for mixed tmux fleets.</li></ul><h3 id="acceptance-criteria-9" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria-9" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h3><ul><li>Docs distinguish Claude Code, Codex CLI, and provider-neutral features.</li><li>Safety limitations are documented without burying them.</li><li>README feature list does not overpromise Codex parity.</li></ul><h2 id="suggested-milestones" tabindex="-1">Suggested Milestones <a class="header-anchor" href="#suggested-milestones" aria-label="Permalink to &quot;Suggested Milestones&quot;">​</a></h2><h3 id="milestone-1-mixed-provider-ux-hardening" tabindex="-1">Milestone 1: Mixed Provider UX Hardening <a class="header-anchor" href="#milestone-1-mixed-provider-ux-hardening" aria-label="Permalink to &quot;Milestone 1: Mixed Provider UX Hardening&quot;">​</a></h3><ul><li>Agent Bridge v2</li><li>Capability matrix</li><li>Header/dashboard/sidebar refinements</li><li>E2E smoke for provider switching and mixed sessions</li></ul><h3 id="milestone-2-codex-config-and-history-depth" tabindex="-1">Milestone 2: Codex Config and History Depth <a class="header-anchor" href="#milestone-2-codex-config-and-history-depth" aria-label="Permalink to &quot;Milestone 2: Codex Config and History Depth&quot;">​</a></h3><ul><li>Profile resolver</li><li>Rules/features/profile cards</li><li>History/model cache investigation</li><li>Usage/context decision doc</li></ul><h3 id="milestone-3-safe-mutation-and-recovery" tabindex="-1">Milestone 3: Safe Mutation and Recovery <a class="header-anchor" href="#milestone-3-safe-mutation-and-recovery" aria-label="Permalink to &quot;Milestone 3: Safe Mutation and Recovery&quot;">​</a></h3><ul><li>Plugin mutation, if CLI behavior is stable</li><li>Backup restore preview and safe restore policy</li><li>Additional command/path validation tests</li></ul><h3 id="milestone-4-provider-platform-hardening" tabindex="-1">Milestone 4: Provider Platform Hardening <a class="header-anchor" href="#milestone-4-provider-platform-hardening" aria-label="Permalink to &quot;Milestone 4: Provider Platform Hardening&quot;">​</a></h3><ul><li>Provider contract cleanup</li><li>Third-provider readiness audit</li><li>Docs refresh</li></ul><h2 id="issue-breakdown" tabindex="-1">Issue Breakdown <a class="header-anchor" href="#issue-breakdown" aria-label="Permalink to &quot;Issue Breakdown&quot;">​</a></h2><p>Create one umbrella GitHub issue for this plan, then track implementation with child issues:</p><ul><li>Agent Bridge v2 mixed-provider UX</li><li>Codex history and model cache investigation</li><li>Codex plugin mutation workflows</li><li>Codex config depth and profile resolver</li><li>Codex backup restore policy</li><li>Provider capability matrix</li><li>Codex usage/context parity investigation</li><li>Provider contract hardening</li><li>Multi-provider E2E smoke coverage</li><li>Multi-provider docs refresh</li></ul><h2 id="open-questions" tabindex="-1">Open Questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open Questions&quot;">​</a></h2><ul><li>Does Codex expose stable enough history/session metadata to deserve a real Sessions page?</li><li>Should Codex plugin mutation be supported immediately, or kept behind an experimental flag?</li><li>Should Codex backup restore support profile/rules files before main <code>config.toml</code>?</li><li>Should the app publicly stay &quot;Claude Deck&quot; while internally becoming a provider-neutral agent console?</li><li>Is there a third provider we expect soon enough to shape the provider contract now?</li></ul><h2 id="recommended-next-step" tabindex="-1">Recommended Next Step <a class="header-anchor" href="#recommended-next-step" aria-label="Permalink to &quot;Recommended Next Step&quot;">​</a></h2><p>Start with Milestone 1. Mixed-provider UX and capability metadata are the right next investment because they reduce confusion across every later Codex feature. Plugin mutation and restore are more dangerous; they should wait until the provider model and test coverage are stronger.</p>',100)])])}const m=i(t,[["render",l]]);export{p as __pageData,m as default};
